 using System.Text.Json;
 using System.Text.Json.Serialization.Metadata;

 // Options with the default reflection-based resolver
 var options = new JsonSerializerOptions(JsonSerializerDefaults.Web)
 {
     TypeInfoResolver = new DefaultJsonTypeInfoResolver()
 };

 // 1) GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
 JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
 Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

 string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
 Console.WriteLine($"Serialized: {json}");

 // 2) TryGetTypeInfo<T>() — probe without throwing
 if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
 {
     Console.WriteLine($"TryGet succeeded for {info!.Type.Name}");
 }

 // Now demonstrate a case where metadata is NOT available:
 // Use a resolver that only knows about Person.
 var limited = new JsonSerializerOptions
 {
     TypeInfoResolver = new DefaultJsonTypeInfoResolver()
         .WithAddedModifier(ti =>
         {
             // Artificially reject anything that isn't Person
             if (ti.Type != typeof(Person))
                 ti.Properties.Clear(); // still "resolves" — let's use a custom empty resolver instead
         })
 };

 // A truly restrictive resolver: returns null for Order
 var empty = new JsonSerializerOptions
 {
     TypeInfoResolver = JsonTypeInfoResolver.Combine() // resolves nothing
 };

 if (empty.TryGetTypeInfo<Order>(out JsonTypeInfo<Order>? orderInfo))
 {
     Console.WriteLine($"Unexpected: got info for {orderInfo!.Type.Name}");
 }
 else
 {
     Console.WriteLine("TryGet for Order returned false — no metadata available (no exception thrown)");
 }

 // Types used in the demo
 public record Person(string Name, int Age);
 public record Order(int Id, decimal Total);

